3: import tools.jackson.databind.JsonNode;
4: 
5: /**
6:  * Incident parser for an observed empty auxiliary-action array in a terminal shootout.
7:  *
8:  * <p>V15 preserves every V14 rule. It treats an omitted
9:  * {@code footballPassingNetworkAction} property and an exact empty JSON array as equivalent only
10:  * while the inherited V12 policy has already established a coherent terminal, wholly unminuted
11:  * shootout. Explicit {@code null}, non-array values and non-empty arrays are not widened by this
12:  * version. Mixed timed and unminuted shootouts remain schema incompatibilities.</p>
13:  */
14: public class EventIncidentsV15Parser extends EventIncidentsV14Parser {
15: 
16:     public static final String PARSER_VERSION = "event-incidents-v15";
17: 
18:     @Override
19:     protected String parserVersion() {
20:         return PARSER_VERSION;
21:     }
22: 
23:     @Override
24:     protected boolean acceptsUnminutedShootoutAction(JsonNode action) {
25:         return action == null || (action.isArray() && action.isEmpty());
26:     }
27: }

1: package com.bettingproject.sofascorelocal.adapter.sofascore.eventdata;
