3: import java.util.Optional;
4: import java.util.Set;
5: 
6: /**
7:  * Incident parser for an observed in-game penalty award before a shot outcome exists.
8:  *
9:  * <p>V16 preserves every V15 rule and adds only the exact {@code inGamePenalty/awarded}
10:  * combination. An award remains an award: it is neither a goal nor a missed attempt. Its
11:  * minute and side retain the ordinary validation, and a supplied player remains validated and
12:  * preserved. A shooter and shot outcome are not expected completeness signals for an award.
13:  * The inherited penalty coherence checks still reject an award carrying a scored or missed
14:  * outcome, and every other incident-class vocabulary remains unchanged. V16 also returns the
15:  * existing atomic-field problem for a one-sided score before attempting domain construction;
16:  * it does not complete or normalize away that incomplete pair.</p>
17:  */
18: public class EventIncidentsV16Parser extends EventIncidentsV15Parser {
19: 
20:     public static final String PARSER_VERSION = "event-incidents-v16";
21: 
22:     private static final Set<String> IN_GAME_PENALTY_CLASSES = Set.of("missed", "awarded");
23: 
24:     @Override
25:     protected String parserVersion() {
26:         return PARSER_VERSION;
27:     }
28: 
29:     @Override
30:     protected Set<String> inGamePenaltyClasses() {
31:         return IN_GAME_PENALTY_CLASSES;
32:     }
33: 
34:     @Override
35:     protected boolean expectsPenaltyOutcomeDetails(
36:             String type,
37:             Optional<String> incidentClass) {
38:         return !("inGamePenalty".equals(type)
39:                 && incidentClass.filter("awarded"::equals).isPresent());
40:     }
41: 
42:     @Override
43:     protected boolean rejectIncompleteScoreBeforeConstruction() {
44:         return true;
45:     }
46: }

