1: package com.bettingproject.sofascorelocal.application.history;
2: 
3: import com.bettingproject.sofascorelocal.domain.event.EventSourceKind;
4: import com.bettingproject.sofascorelocal.domain.event.EventSourceTrace;
5: import com.bettingproject.sofascorelocal.domain.history.J6ChangeKind;
6: import com.bettingproject.sofascorelocal.domain.history.J6HistoryClassification;
7: import com.bettingproject.sofascorelocal.domain.history.J6SemanticChange;
8: import com.bettingproject.sofascorelocal.domain.history.J6VersionSignature;
9: import org.springframework.stereotype.Service;
10: 
11: import java.util.List;
12: import java.util.Locale;
13: import java.util.Objects;
14: import java.util.Optional;
15: import java.util.Set;
16: 
17: @Service
18: public class J6HistoryClassifier {
19: 
20:     private static final Set<String> TERMINAL_STATUSES = Set.of(
21:             "finished",
22:             "canceled",
23:             "cancelled",
24:             "abandoned",
25:             "walkover");
26: 
27:     public J6HistoryClassification classify(
28:             Optional<J6VersionSignature> before,
29:             J6VersionSignature after,
30:             boolean terminalBefore,
31:             List<J6SemanticChange> changes) {
32:         Objects.requireNonNull(before, "before");
33:         Objects.requireNonNull(after, "after");
34:         changes = List.copyOf(Objects.requireNonNull(changes, "changes"));
35:         if (before.isEmpty()) {
36:             return J6HistoryClassification.BASELINE;
37:         }
38:         J6VersionSignature previous = before.orElseThrow();
39:         EventSourceTrace oldSource = previous.source();
40:         EventSourceTrace newSource = after.source();
41: 
42:         if (sameProviderSnapshot(oldSource, newSource)
43:                 && oldSource.parserVersion().equals(newSource.parserVersion())
44:                 && previous.normalizedSha256().equals(after.normalizedSha256())) {
45:             return J6HistoryClassification.TECHNICAL_DUPLICATE;
46:         }
47:         if (oldSource.payloadSha256().equals(newSource.payloadSha256())
48:                 && (!oldSource.parserVersion().equals(newSource.parserVersion())
49:                         || !previous.normalizedSha256().equals(after.normalizedSha256()))) {
50:             return J6HistoryClassification.LOCAL_REPARSE;
51:         }
52:         if (!oldSource.payloadSha256().equals(newSource.payloadSha256())
53:                 && previous.normalizedSha256().equals(after.normalizedSha256())) {
54:             return J6HistoryClassification.SEMANTICALLY_UNCHANGED;
55:         }
56:         if (newSource.kind() == EventSourceKind.SYNTHETIC_FIXTURE) {
57:             return J6HistoryClassification.SYNTHETIC_CHANGE;
58:         }
59:         if (!terminalBefore) {
60:             return J6HistoryClassification.PROVIDER_UPDATE;
61:         }
62:         return isAdditionsOnly(changes)
63:                 ? J6HistoryClassification.LATE_ENRICHMENT
64:                 : J6HistoryClassification.LATE_CORRECTION;
65:     }
66: 
67:     public boolean isTerminalStatus(String statusType) {
68:         if (statusType == null) {
69:             return false;
70:         }
71:         return TERMINAL_STATUSES.contains(statusType.trim().toLowerCase(Locale.ROOT));
72:     }
73: 
74:     private static boolean sameProviderSnapshot(
75:             EventSourceTrace before,
76:             EventSourceTrace after) {
77:         return before.kind() == EventSourceKind.PROVIDER_SNAPSHOT
78:                 && after.kind() == EventSourceKind.PROVIDER_SNAPSHOT
79:                 && before.snapshotId().isPresent()
80:                 && after.snapshotId().isPresent()
81:                 && before.snapshotId().getAsLong() == after.snapshotId().getAsLong();
82:     }
83: 
84:     private static boolean isAdditionsOnly(List<J6SemanticChange> changes) {
85:         List<J6SemanticChange> substantive = changes.stream()
86:                 .filter(change -> !change.field().startsWith("completeness."))
87:                 .filter(change -> !change.field().startsWith("score."))
88:                 .toList();
89:         return !substantive.isEmpty()
90:                 && substantive.stream().allMatch(change -> change.kind() == J6ChangeKind.ADDED);
91:     }
92: }

