190:     private static void compareStatistics(
191:             List<J6SemanticChange> changes,
192:             EventStatistics before,
193:             EventStatistics after) {
194:         Map<StatisticKey, List<EventStatisticMetric>> beforeByKey = groupBy(
195:                 before.metrics(), StatisticKey::from);
196:         Map<StatisticKey, List<EventStatisticMetric>> afterByKey = groupBy(
197:                 after.metrics(), StatisticKey::from);
198:         Set<StatisticKey> keys = orderedUnion(
199:                 beforeByKey.keySet(),
200:                 afterByKey.keySet(),
201:                 Comparator.comparing(StatisticKey::label));
202:         for (StatisticKey key : keys) {
203:             List<EventStatisticMetric> oldValues = mutable(beforeByKey.get(key));
204:             List<EventStatisticMetric> newValues = mutable(afterByKey.get(key));
205:             removeExactMatches(oldValues, newValues);
206:             String path = "statistics[" + key.label() + "]";
207:             if (oldValues.size() == 1 && newValues.size() == 1) {
208:                 EventStatisticMetric oldValue = oldValues.getFirst();
209:                 EventStatisticMetric newValue = newValues.getFirst();
210:                 scalar(changes, path + ".label", oldValue.metricName(), newValue.metricName());
211:                 scalar(changes, path + ".home",
212:                         oldValue.homeValue().orElse(null), newValue.homeValue().orElse(null));
213:                 scalar(changes, path + ".away",
214:                         oldValue.awayValue().orElse(null), newValue.awayValue().orElse(null));
215:                 continue;
216:             }
217:             removeEntities(changes, path, oldValues, J6SemanticDiffService::statisticSummary);
218:             addEntities(changes, path, newValues, J6SemanticDiffService::statisticSummary);
219:         }
220:     }
