351:     private static void compareIncidents(
352:             List<J6SemanticChange> changes,
353:             EventIncidents before,
354:             EventIncidents after) {
355:         List<PositionedIncident> oldValues = positioned(before.incidents());
356:         List<PositionedIncident> newValues = positioned(after.incidents());
357:         List<IncidentPair> pairs = new ArrayList<>();
358: 
359:         pairExactIncidents(oldValues, newValues);
360:         pairUnique(
361:                 oldValues,
362:                 newValues,
363:                 incident -> incident.incident().shootoutSequence()
364:                         .map(value -> "shootout:" + value)
365:                         .orElse(null),
366:                 pairs);
367:         pairUnique(
368:                 oldValues,
369:                 newValues,
370:                 incident -> providerIncidentKey(incident.incident()),
371:                 pairs);
372:         pairUnique(
373:                 oldValues,
374:                 newValues,
375:                 incident -> positionalIncidentKey(incident.incident()),
376:                 pairs);
377: 
378:         pairs.sort(Comparator.comparingInt(pair -> pair.after().position()));
379:         for (IncidentPair pair : pairs) {
380:             compareIncident(changes, pair.before(), pair.after());
381:         }
382:         oldValues.sort(Comparator.comparingInt(PositionedIncident::position));
383:         newValues.sort(Comparator.comparingInt(PositionedIncident::position));
384:         removeEntities(changes, "incidents", oldValues,
385:                 value -> incidentSummary(value.incident()));
386:         addEntities(changes, "incidents", newValues,
387:                 value -> incidentSummary(value.incident()));
388: 
389:         Optional<J6Score> beforeScore = scoreFrom(before);
390:         Optional<J6Score> afterScore = scoreFrom(after);
391:         scalar(changes, "score.home",
392:                 beforeScore.map(J6Score::home).orElse(null),
393:                 afterScore.map(J6Score::home).orElse(null));
394:         scalar(changes, "score.away",
395:                 beforeScore.map(J6Score::away).orElse(null),
396:                 afterScore.map(J6Score::away).orElse(null));
397:     }
