406:                 + ",after=" + newValue.sequence() + "]";
407:         scalar(changes, path + ".order", oldValue.sequence(), newValue.sequence());
408:         scalar(changes, path + ".type", oldValue.incidentType(), newValue.incidentType());
409:         scalar(changes, path + ".minute",
410:                 oldValue.minute().orElse(null), newValue.minute().orElse(null));
411:         scalar(changes, path + ".addedTime",
412:                 oldValue.addedTime().orElse(null), newValue.addedTime().orElse(null));
413:         scalar(changes, path + ".side",
414:                 oldValue.home().map(value -> value ? "HOME" : "AWAY").orElse(null),
415:                 newValue.home().map(value -> value ? "HOME" : "AWAY").orElse(null));
416:         scalar(changes, path + ".participantProviderId",
417:                 oldValue.participantProviderId().orElse(null),
418:                 newValue.participantProviderId().orElse(null));
419:         scalar(changes, path + ".playerProviderId",
420:                 oldValue.playerProviderId().orElse(null),
421:                 newValue.playerProviderId().orElse(null));
422:         scalar(changes, path + ".playerName",
423:                 oldValue.playerName().orElse(null), newValue.playerName().orElse(null));
424:         scalar(changes, path + ".playerInProviderId",
425:                 oldValue.playerInProviderId().orElse(null),
426:                 newValue.playerInProviderId().orElse(null));
427:         scalar(changes, path + ".playerInName",
428:                 oldValue.playerInName().orElse(null), newValue.playerInName().orElse(null));
429:         scalar(changes, path + ".playerOutProviderId",
430:                 oldValue.playerOutProviderId().orElse(null),
431:                 newValue.playerOutProviderId().orElse(null));
