529:     private static Map<String, List<PositionedIncident>> incidentGroups(
530:             List<PositionedIncident> values,
531:             Function<PositionedIncident, String> keyFunction) {
532:         Map<String, List<PositionedIncident>> result = new LinkedHashMap<>();
533:         for (PositionedIncident value : values) {
534:             String key = keyFunction.apply(value);
535:             if (key != null) {
536:                 result.computeIfAbsent(key, ignored -> new ArrayList<>()).add(value);
537:             }
538:         }
539:         return result;
540:     }
